-- ATELO — catalog_products seed for Supabase.
-- Paste into the Supabase SQL Editor and Run. Safe to re-run (idempotent).
--
-- Superset of lib/catalog.ts: 857 finishes & products, weighted toward
-- paint colours with accurate hex values from real ranges (Farrow & Ball,
-- Benjamin Moore, Sherwin-Williams, Little Greene, Dulux Heritage) plus stone,
-- wood, metal, tile, cladding, lighting and fixture finishes.

-- ---------- Table ----------
create table if not exists catalog_products (
  id text primary key,
  category text not null,
  brand text,
  name text not null,
  hex text,
  finish text,
  description text,
  tags text[],
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

-- ---------- Row Level Security ----------
alter table catalog_products enable row level security;

-- Public read policy (guarded so re-running does not error).
do $$
begin
  create policy "catalog public read" on catalog_products for select using (true);
exception
  when duplicate_object then null;
end
$$;

-- ---------- Seed data ----------
on conflict (id) do nothing;
